catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

   var cat = g_form.getValue('variables.hazard_category');
	alert(cat);

	switch(cat){
		case 'chemical':
			g_form.clearOptions('hazard_subcategory');
			g_form.addOption('hazard_subcategory', 'carcinogenic', 'Carcinogenic');
			g_form.addOption('hazard_subcategory', 'mutagenic', 'Mutagenic');
			g_form.addOption('hazard_subcategory', 'sensitizers', 'Sensitizers');
			g_form.addOption('hazard_subcategory', 'flammable', 'Flammable');
			g_form.addOption('hazard_subcategory', 'oxidizing', 'Oxidizing');
			g_form.addOption('hazard_subcategory', 'corrosive', 'Corrosive');
			g_form.addOption('hazard_subcategory', 'acute toxicity', 'Acute Toxicity');
			break;
		case 'biological':
			g_form.clearOptions('hazard_subcategory');
			g_form.addOption('hazard_subcategory', 'plant', 'Plant');
			g_form.addOption('hazard_subcategory', 'animal', 'Animal');
			g_form.addOption('hazard_subcategory', 'microbiological', 'Microbiological');
			break;
		case 'physical':
			g_form.clearOptions('hazard_subcategory');
			g_form.addOption('hazard_subcategory', 'environmental', 'Environmental');
			g_form.addOption('hazard_subcategory', 'mechanical', 'Mechanical');
			g_form.addOption('hazard_subcategory', 'musculoskeletal', 'Musculoskeletal');
			break;
		case 'energy':
			g_form.clearOptions('hazard_subcategory');
			g_form.addOption('hazard_subcategory', 'electrical', 'Electrical');
			g_form.addOption('hazard_subcategory', 'magnetic', 'Magnetic');
			g_form.addOption('hazard_subcategory', 'electromagnetic_interference', 'Electromagnetic Interference');
			g_form.addOption('hazard_subcategory', 'thermal', 'Thermal');
			g_form.addOption('hazard_subcategory', 'noise', 'Noise');
			g_form.addOption('hazard_subcategory', 'vibration', 'Vibration');
			g_form.addOption('hazard_subcategory', 'radiation', 'Radiation');
			g_form.addOption('hazard_subcategory', 'laser', 'Laser');
			break;
		case 'explosion':
			g_form.clearOptions('hazard_subcategory');
			g_form.addOption('hazard_subcategory', 'chemical', 'Chemical');
			g_form.addOption('hazard_subcategory', 'mechanical', 'Mechanical');
			break;
		case 'psychosocial':
			g_form.clearOptions('hazard_subcategory');
			g_form.addOption('hazard_subcategory', 'cognitive', 'Cognitive');
			g_form.addOption('hazard_subcategory', 'human_reliability', 'Human Reliability');
			g_form.addOption('hazard_subcategory', 'social', 'Social');
			g_form.addOption('hazard_subcategory', 'work_organization', 'Work Organization');
			break;
		default:
			break;			
	}

}
